import {state,esc,dateKey} from '../../lib/store.js';
import {categories,categoryNames,sessionsInRange,heatLevel} from '../../lib/progress/model.js';
import {input,area} from '../pixel/primitives.js';
import {action,box,glyph,cat,meter,categoryIcon,titleHeader} from '../mission/shared.js';
const focusFmt=minutes=>`${String(Math.floor(minutes/60)).padStart(2,'0')}时 ${String(Math.round(minutes%60)).padStart(2,'0')}分`;
export function sessionForm(record=null,draft={}){const r=record||{category:draft.category||'RESEARCH',durationMinutes:draft.durationMinutes??'',date:draft.date||dateKey(),linkedTaskId:draft.linkedTaskId||'',note:draft.note||''},tasks=state.tasks.filter(t=>!t.done||String(t.id)===r.linkedTaskId);return `<form data-form="focus-log" data-id="${esc(record?.id||'')}" class="focus-log-form"><fieldset><legend>1. 今天专注了什么？</legend><div class="focus-categories">${categories.map(c=>`<label class="cat-${c}"><input type="radio" name="category" value="${c}" ${r.category===c?'checked':''} required><span>${categoryIcon(c)}${esc(categoryNames[c])}</span></label>`).join('')}</div></fieldset><label class="duration-label" for="focus-duration-${record?'edit':'new'}">2. 专注时长</label><div class="duration-entry"><input id="focus-duration-${record?'edit':'new'}" name="durationMinutes" type="number" required min="1" max="1440" step="1" value="${esc(r.durationMinutes)}" placeholder="0" aria-label="专注分钟"><span>分钟</span></div><div class="duration-shortcuts">${[15,30,45,60].map(n=>action('+'+n,'focus-add',`data-value="${n}"`)).join('')}</div>${input('date','专注日期',r.date,'date',`required max="${dateKey()}"`)}<label class="field"><span>3. 关联任务（可选）</span><select name="linkedTaskId"><option value="">无</option>${tasks.map(t=>`<option value="${esc(t.id)}" ${String(t.id)===r.linkedTaskId?'selected':''}>${esc(t.title)}${t.done?' / 已完成':''}</option>`).join('')}${r.linkedTaskId&&!tasks.some(t=>String(t.id)===r.linkedTaskId)?`<option value="${esc(r.linkedTaskId)}" selected>${esc(r.linkedTaskTitle||'已删除的任务')}</option>`:''}</select></label>${area('note','4. 备注（可选）',r.note,'maxlength="10000"')}<button class="mc-button primary log-session" type="submit">${record?'保存修改':'+ 记录专注'}${cat()}</button>${record?action('取消','close'):''}<p class="focus-privacy">仅本地数据 · 记录专注不会完成任务或发放经验值。</p></form>`}
function overview(ui){const range=ui.focusRange||'today',rangeLabels={today:'今天',week:'本周',month:'本月',year:'本年'},records=sessionsInRange(state,range),total=records.reduce((n,s)=>n+s.durationMinutes,0);return box(`${glyph('chart',20)} 专注概览`,`<div class="focus-overview"><div class="focus-total"><span>累计专注时长</span><strong>${focusFmt(total)}</strong><small>${records.length} 条记录 · ${rangeLabels[range]}</small></div><div class="focus-distribution">${categories.map(c=>{const minutes=records.filter(s=>s.category===c).reduce((n,s)=>n+s.durationMinutes,0),pct=total?Math.round(minutes/total*100):0;return `<div class="focus-distribution-row cat-${c}"><span>${categoryIcon(c)}${esc(categoryNames[c])}</span>${meter(pct,categoryNames[c])}<small>${pct}%</small><small>${focusFmt(minutes)}</small></div>`}).join('')}</div></div>`,`<div class="focus-range-tabs">${['today','week','month','year'].map(key=>action(rangeLabels[key],'focus-range',`data-value="${key}" aria-pressed="${key===range}"`,key===range?'active':'')).join('')}</div>`)}
function heatmap(ui){const ym=ui.focusMonth||dateKey().slice(0,7),[y,m]=ym.split('-').map(Number),first=new Date(y,m-1,1),offset=(first.getDay()+6)%7,last=new Date(y,m,0).getDate(),weeks=Math.ceil((offset+last)/7),totals=new Map();state.sessions.forEach(s=>totals.set(s.date,(totals.get(s.date)||0)+s.durationMinutes));return box(`${glyph('calendar',20)} 专注活动 // ${y}年${m}月`,`<div class="heatmap-wrap"><div class="heatmap-days">${['一','二','三','四','五','六','日'].map(d=>`<span>${d}</span>`).join('')}</div><div class="focus-heatmap" style="--weeks:${weeks}">${Array.from({length:weeks*7},(_,i)=>{const n=i-offset+1;if(n<1||n>last)return '<span class="heat-blank"></span>';const date=ym+'-'+String(n).padStart(2,'0'),minutes=totals.get(date)||0;return `<button type="button" class="heat-cell level-${heatLevel(minutes)}" data-action="focus-day" data-value="${date}" aria-label="${date} · ${minutes} 分钟" title="${date}: ${minutes} 分钟">${n}</button>`}).join('')}</div><div class="heatmap-legend">${[[4,'≥ 120 分钟'],[3,'61–119 分钟'],[2,'31–60 分钟'],[1,'1–30 分钟'],[0,'无专注']].map(([n,t])=>`<span><i class="level-${n}"></i>${t}</span>`).join('')}</div></div>`,`<div>${action('‹','focus-month','data-value="-1" aria-label="专注上个月"','tiny')}${action('›','focus-month','data-value="1" aria-label="专注下个月"','tiny')}</div>`)}
export function sessionsTable(ui){let list=state.sessions.slice().sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||'').localeCompare(a.createdAt||''));if(ui.focusDate)list=list.filter(s=>s.date===ui.focusDate);if(!ui.focusAll&&!ui.focusDate)list=list.slice(0,5);return box('最近专注记录',`${ui.focusDate?`<p class="micro">${ui.focusDate} ${action('清除','focus-day','data-value=""','tiny')}</p>`:''}<div class="session-table"><div class="session-row session-label"><span>日期</span><span>分类</span><span>时长</span><span>关联任务 / 备注</span><span></span></div>${list.map(s=>`<div class="session-row"><span>${esc(s.date.slice(5))}</span><span class="cat-${s.category}">${categoryIcon(s.category)}${esc(categoryNames[s.category]||s.category)}</span><span>${s.durationMinutes} 分钟</span><span class="session-note" title="${esc(s.note)}">${esc(state.tasks.find(t=>String(t.id)===s.linkedTaskId)?.title||s.linkedTaskTitle||s.note||'—')}</span>${action('···','focus-menu',`data-id="${esc(s.id)}" aria-label="专注记录菜单 ${esc(s.date)}"`,'tiny')}</div>`).join('')||'<p class="mc-empty">暂无专注记录</p>'}</div>`,action(ui.focusAll?'显示最近记录':'查看全部 →','focus-all','','tiny'))}
export function focusMenu(id){const s=state.sessions.find(s=>s.id===id);if(!s)return '';return `<h3>${esc(categoryNames[s.category]||s.category)} · ${s.durationMinutes} 分钟</h3><p>${esc(s.date)}</p><p class="pre">${esc(s.note||'无备注')}</p><p>${esc(s.linkedTaskTitle||'未关联任务')}</p><div class="actions">${action('编辑','focus-edit',`data-id="${esc(s.id)}"`)}${action('删除','focus-delete',`data-id="${esc(s.id)}"`,'danger')}</div>`}
export function focus(ui){return `${titleHeader('专注舱','专注记录','小步前进，<br>故事仍在继续。','focus')}<div class="manual-focus-body"><div class="focus-entry">${box(`${glyph('mission',22)} 记录一次专注`,sessionForm(null,state.focusDraft||{}))}</div><div class="focus-data">${overview(ui)}${heatmap(ui)}${sessionsTable(ui)}</div></div>`}
